describe('Dynamic Content Loading - The Internet', () => {
  beforeEach(() => {
    cy.visit('https://the-internet.herokuapp.com/dynamic_loading/1');
  });

  it('should reveal hidden content after asynchronous load with loading indicator', () => {
    // Verify initial state: loading indicator is visible, finish button is hidden
    cy.get('[data-testid="loading"]').should('be.visible');
    cy.get('#finish').should('not.exist');

    // Click the Start button to initiate loading
    cy.get('#start').click();

    // Wait for the loading indicator to disappear
    cy.get('[data-testid="loading"]').should('not.exist');

    // Verify loading indicator is gone
    cy.get('[data-testid="loading"]').should('not.exist');

    // Verify the finish button is now visible
    cy.get('#finish').should('be.visible');

    // Verify the content is loaded and visible
    cy.get('#content').should('contain', 'Hello World!');

    // Verify the page footer is still visible
    cy.get('#page-footer').should('be.visible');
  });

  it('should handle failed content load and display error message', () => {
    // Mock the async load to fail
    cy.intercept('GET', '/api/content', {
      statusCode: 500,
      body: { error: 'Internal Server Error' }
    }).as('loadContent');

    // Click the Start button to initiate loading
    cy.get('#start').click();

    // Wait for the failed load response
    cy.wait('@loadContent');

    // Verify loading indicator is still visible
    cy.get('[data-testid="loading"]').should('be.visible');

    // Verify the finish button is still visible but disabled
    cy.get('#finish').should('be.visible');
    cy.get('#finish').should('have.attr', 'disabled');

    // Verify error message is displayed
    cy.get('#flash-messages').should('contain', 'Failed to load content');

    // Verify the page footer is still visible
    cy.get('#page-footer').should('be.visible');
  });
});
